import { useObserver } from "mobx-react-lite";
import store from './store';
import styles from './index.module.less';
import { DragView } from "react-converter-code";
import { Divider } from "@arco-design/web-react";
import { getArcoIcon, getArcoIconModule } from "@/utils/icon";


const IconList = () => {

    return (
        <div style={{ height: '80vh', overflowY: 'auto' }}>
        {store.categoryList.map((o) => {
            return (
                <div key={o.key}>
                    <Divider orientation="center">
                        {o.title}
                    </Divider>
                    <div className={styles['icon-list']}>
                        {o.list.map((key) => {
                            const Element = getArcoIcon(key);
                            return (
                                <DragView key={key} className={styles['icon-item']} data={getArcoIconModule(key)}>
                                    <div className={styles['icon-view']}>
                                        <Element />
                                        <div style={{ fontSize: 10, marginTop: 10 }}>{key.replace("Icon", '')}</div>
                                    </div>
                                    {/* <div className={styles['icon-name']}>
                                        {key}
                                    </div> */}
                                </DragView>
                            )
                        })}
                    </div>
                </div>
            )
        })}
        </div>
    )
};

export default IconList;